class EventQueue:
    def __init__(self):
        self._items = {}
        self._next_id = 0

    def add(self, event):
        self._items[self._next_id] = event
        self._next_id += 1

    def drain(self):
        items = list(self._items.values())
        self._items = {}
        return items
